cat >> parser_test.go <<'E'

func TestLookupDottedSection(t *testing.T) {
	c, err := Parse(strings.NewReader("top = 1\n[db.eu]\nhost = h\n"))
	if err != nil {
		t.Fatal(err)
	}
	for name, want := range map[string]string{"db.eu.host": "h", "top": "1"} {
		if got, err := c.Lookup(name); err != nil || got != want {
			t.Errorf("Lookup(%q) = %q, %v; want %q", name, got, err, want)
		}
	}
}
E
